import{at as e,it as t,t as n,vt as r}from"./chunks/framework.B8HA7oqK.js";var i=JSON.parse(`{"title":"","description":"","frontmatter":{"layout":"home","hero":{"name":"Project X","text":"Xray-core","tagline":"Fear not the clouds that obscure the view, golden eyes like a torch brighten the sky","image":{"src":"/img-project-x.png","alt":"Xray, Penetrates Everything"},"actions":[{"theme":"brand","text":"Quickstart","link":"/en/document/"},{"theme":"alt","text":"Configuration guide","link":"/en/config/"},{"theme":"alt","text":"Sponsor & Donation & NFTs","link":"/en/about/sponsor.md"}]},"features":[{"title":"Original protocols","icon":"📄","details":"Original protocols such as VLESS, XTLS, XUDP, XHTTP, and REALITY cover proxying, flow control, multiplexing, transport, and security."},{"title":"Powerful routing","icon":"🔀","details":"A flexible routing and DNS system supports fine-grained traffic scheduling by domain, IP, port, protocol, process, user, and more."},{"title":"Traffic camouflage","icon":"🎭","details":"VLESS fallback, REALITY, XTLS flow control, FinalMask, and related approaches reduce traffic fingerprints and improve resistance to detection at multiple layers."},{"title":"Free combination","icon":"🧩","details":"Proxy protocols, flow-control modes, transport layers, and the routing system can be freely combined to fit different scenarios."},{"title":"Ultra-low overhead","icon":"📊","details":"VLESS removes redundant encryption, and Splice cuts forwarding overhead, making OpenWRT, Raspberry Pi, and other lightweight devices practical targets."},{"title":"Community-driven","icon":"💖","details":"Active community discussion and contributions under the MPL 2.0 open-source license."}]},"headers":[],"relativePath":"en/index.md","filePath":"en/index.md","lastUpdated":1778396361000}`),a={name:`en/index.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h2 id="xtls-xray-v2ray" tabindex="-1">XTLS? Xray? V2Ray? <a class="header-anchor" href="#xtls-xray-v2ray" aria-label="Permalink to “XTLS? Xray? V2Ray?”">​</a></h2><blockquote><p><strong>XTLS are brilliant ideas for TLS we study, while Xray is the best practice we maintain.</strong></p></blockquote><ul><li>Xray-core originally branched from v2ray-core, but it has evolved independently for a long time and should no longer be treated as a fully compatible drop-in replacement. <ul><li>Only one executable file, including ctl functionality, run is the default command</li><li>Some configuration structures and usage patterns still resemble v2ray-core, but environment variables, API prefixes, and many features are already different</li><li>Exposed raw protocol&#39;s ReadV on all platforms</li><li>Provides complete support for VLESS, XTLS Vision, and REALITY</li><li>Provides multiple XTLS flow-control modes and can deliver extremely high performance with Splice in suitable scenarios</li></ul></li></ul><h3 id="who-are-we" tabindex="-1">Who are we? <a class="header-anchor" href="#who-are-we" aria-label="Permalink to “Who are we?”">​</a></h3><blockquote><p><strong>It doesn&#39;t matter who we are. What matters is that we will keep riding and never look back.</strong></p></blockquote><h3 id="help-xray-become-stronger" tabindex="-1">Help Xray become stronger <a class="header-anchor" href="#help-xray-become-stronger" aria-label="Permalink to “Help Xray become stronger”">​</a></h3><p>Welcome to help Xray become stronger!</p><ul><li>🖥️ Help develop and test Xray, submit high-quality Pull requests.</li><li>📩 Initiate constructive or meaningful issues and discussions in <a href="https://github.com/XTLS/Xray-core/issues" target="_blank" rel="noreferrer">GitHub Issues</a> or <a href="https://github.com/XTLS/Xray-core/discussions" target="_blank" rel="noreferrer">Discussion area</a>.</li><li>📝 Write down your usage experience and submit it to Xray&#39;s <a href="https://github.com/XTLS/Xray-docs-next" target="_blank" rel="noreferrer">documentation website</a>.</li><li>💬 Help group members/chat in Telegram group.</li><li><strong>...In fact, every support for Xray will make Xray stronger.</strong></li></ul><h3 id="telegram" tabindex="-1">Telegram <a class="header-anchor" href="#telegram" aria-label="Permalink to “Telegram”">​</a></h3><ul><li><p><a href="https://t.me/projectXray" target="_blank" rel="noreferrer">Project X Discussion Group</a></p><ul><li>Chinese / English user group. Main chat group.</li></ul></li><li><p><a href="https://t.me/projectVless" target="_blank" rel="noreferrer">Project VLESS Group</a></p><ul><li>Russian user group. Sister group of <a href="https://t.me/projectXray" target="_blank" rel="noreferrer">Project X</a>.</li></ul></li><li><p><a href="https://t.me/projectXHTTP" target="_blank" rel="noreferrer">Project XHTTP Group</a></p><ul><li>Persian user group. Sister group of <a href="https://t.me/projectXray" target="_blank" rel="noreferrer">Project X</a>.</li></ul></li><li><p><a href="https://t.me/projectXtls" target="_blank" rel="noreferrer">Project X Channel</a></p><ul><li>Publish the latest news of Project X.</li></ul></li></ul><h3 id="thanks" tabindex="-1">Thanks <a class="header-anchor" href="#thanks" aria-label="Permalink to “Thanks”">​</a></h3><ul><li>Thanks to everyone for their support!</li><li>Thanks to all kinds of scripts, Docker images, client support... Thanks to all the big guys who helped improve the ecosystem!</li><li>Thanks to friends who have contributed to the Xray website and documentation.</li><li>Thanks to friends who have made meaningful suggestions and comments.</li><li>Thanks to every friend in the Telegram group who helps others.</li></ul><h3 id="more-about-project-x" tabindex="-1">More about project X <a class="header-anchor" href="#more-about-project-x" aria-label="Permalink to “More about project X”">​</a></h3><ul><li>If you would like to learn more about project X&#39;s history and growth, please click <a href="./about/news.html">here</a></li><li>Now Project X releases NFTs! If you would like to have one Project X NFT, or want to donate to or sponsoring Project X, please click <a href="https://github.com/XTLS/Xray-core/discussions/3633" target="_blank" rel="noreferrer">here</a></li></ul><h3 id="license" tabindex="-1">License <a class="header-anchor" href="#license" aria-label="Permalink to “License”">​</a></h3><p><a href="https://github.com/XTLS/Xray-core/blob/main/LICENSE" target="_blank" rel="noreferrer">Mozilla Public License Version 2.0</a></p><h3 id="stargazers-over-time" tabindex="-1">Stargazers over time <a class="header-anchor" href="#stargazers-over-time" aria-label="Permalink to “Stargazers over time”">​</a></h3><p><a href="https://starchart.cc/XTLS/Xray-core" target="_blank" rel="noreferrer"><img src="https://starchart.cc/XTLS/Xray-core.svg?variant=adaptive" alt="Stargazers over time"></a></p>`,18)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};